content.arguments:
{"command": "$PSVersionTable.PSVersion.ToString(); $PSVersionTable.PSEdition
$b = "C:\Users\zakiz\OneDrive\Desktop\ctrl stay works\_audit_extracted"
foreach($f in @("Project Plan 2.0.DOCX","Project Plan 2.0 _1_.DOCX")){
  $p = Join-Path $b $f
  $bytes = Get-Content -LiteralPath $p -AsByteStream -TotalCount 4
  "$f BOM: " + (($bytes | ForEach-Object { $_.ToString('X2') }) -join ' ')
}
foreach($f in @("Project Plan 2.0.DOCX","Project Plan 2.0 _1_.DOCX")){
  $p = Join-Path $b $f
  $t = [System.IO.File]::ReadAllText($p, [System.Text.UTF8Encoding]::new($false))
  "$f -> contains U+20B1 peso: $($t.Contains([char]0x20B1))  contains en-dash: $($t.Contains([char]0x2013))"
}", "description": "Check PS version, BOM, and true UTF-8 decode"}

